-- | Huffman tree data type
data HuffmanTree = Leaf Char Int | Node Int HuffmanTree HuffmanTree
  deriving (Show, Eq)

-- Frequency table
freqMap :: String -> Map Char Int
freqMap = foldr (\c m -> Map.insertWith (+) c 1 m) Map.empty

-- Build Huffman tree from frequency map
buildTree :: Map Char Int -> HuffmanTree
buildTree m
  | Map.null m = error "Empty input"
  | Map.size m == 1 = let (c, f) = Map.findMin m in Leaf c f
  | otherwise = let nodes = map (\(c,f) -> Leaf c f) (Map.toList m)
                    sorted = sortBy (comparing getFreq) nodes
                in build sorted
  where
    getFreq (Leaf _ f)   = f
    getFreq (Node f _ _) = f
    build [t] = t
    build (t1:t2:ts) =
      let merged = Node (getFreq t1 + getFreq t2) t1 t2
      in build (insertByFreq merged ts)
    insertByFreq t [] = [t]
    insertByFreq t (x:xs)
      | getFreq t <= getFreq x = t : x : xs
      | otherwise = x : insertByFreq t xs

-- Generate code map: Char -> [Bool]
codeMap :: HuffmanTree -> Map Char [Bool]
codeMap t = go t []
  where
    go (Leaf c _) bits = Map.insert c bits
    go (Node _ l r) bits = go l (bits ++ [False]) `Map.union` go r (bits ++ [True])

-- Encode string to bits
encodeBits :: HuffmanTree -> String -> [Bool]
encodeBits t = concatMap (\c -> Map.findWithDefault [] c (codeMap t))

-- Decode bits to string
decodeBits :: HuffmanTree -> [Bool] -> String
decodeBits t bits = go bits t
  where
    go [] _ = []
    go bs (Leaf c _) = c : go bs t
    go bs (Node _ l r) =
      case bs of
        [] -> []
        (b:bs') -> if not b then go bs' l else go bs' r

-- Convert Int to 32-bit big-endian bits
intToBits :: Int -> [Bool]
intToBits n = [ testBit n i | i <- [31,30..0] ]
  where
    testBit x i = (x `shiftL` (31-i)) .&. 0x80000000 /= 0

-- Convert 32 bits to Int
bitsToInt :: [Bool] -> Int
bitsToInt bits = foldl (\acc b -> (acc `shiftL` 1) .|. if b then 1 else 0) 0 bits

-- Compress a single string
compress :: String -> [Bool]
compress s = let tree = buildTree s
                 bits = encodeBits tree s
                 header = intToBits (length bits)
             in header ++ bits

